import requests
terms=['haptoglobin hemopexin stored red blood cells resuscitation','haptoglobin hemopexin prolonged storage red cells','haptoglobin therapy transfusion stored red blood cells acute effects','hemopexin resuscitation stored red cells']
for q in terms:
 u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
 r=requests.get(u,params={'db':'pubmed','term':q,'retmode':'json','retmax':10},timeout=20)
 print('\nQUERY:',q,'STATUS',r.status_code)
 if r.ok:
  ids=r.json()['esearchresult']['idlist']; print('PMIDs:',','.join(ids) or 'none')
  if ids:
   s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20)
   for i in ids:
    x=s.json()['result'][i]; print(i,x.get('title'),x.get('pubdate'))
 else: print(r.text[:200])
